function masteryHome(){const done=COURSE.mastery.filter(m=>saved.notes[1000+m.id]==='complete').length;return heading('GO DEEPER · INTERVIEW MASTERY','Reason clearly. Solve unfamiliar problems.','A rigorous extension for Google-level coding preparation, built on your foundation path.')+`<div class="hero"><div><div class="eyebrow">DEPTH OVER QUESTION COUNT</div><h2>From knowing a pattern<br>to defending a solution.</h2><p>14 detailed lessons, 6 original interview labs, proofs, worked examples, and constraint-changing follow-ups. Your existing progress stays intact.</p><a class="btn" href="#deep/0">Start the mastery track →</a></div><div class="hero-art">${art}</div></div><div class="controls"><a class="btn light" href="#labs">Original interview labs →</a><a class="btn light" href="#readiness">Readiness scorecard →</a><a class="btn light" href="mastery-guide.md" download>Download deep-dive guide ↓</a></div><p class="note">${done} / ${COURSE.mastery.length} lesson gates self-verified. This is independent preparation, not an official Google curriculum or a hiring guarantee. Use current recruiter instructions for your interview format.</p><div class="grid">${COURSE.mastery.map(m=>`<article class="card"><a class="stretched" href="#deep/${m.id}"><div class="card-top"><span class="phase-icon">${String(m.id+1).padStart(2,'0')}</span><span class="tag">${saved.notes[1000+m.id]==='complete'?'GATE VERIFIED':'DEEP DIVE'}</span></div><h3>${esc(m.title)}</h3><p>Theory · Reasoning · Practice · Follow-ups</p><div class="card-bottom"><span>Open lesson</span><span>→</span></div></a></article>`).join('')}</div>`}
function deepPage(id){const m=COURSE.mastery[+id];if(!m)return '<p>Lesson not found. <a href="#mastery">Return to mastery.</a></p>';return heading('MASTERY LESSON '+String(m.id+1).padStart(2,'0'),esc(m.title),'Derive it. Prove it. Implement it. Change an assumption.')+`<div class="controls"><a class="btn light" href="#mastery">← All lessons</a><button class="btn" onclick="saved.notes[${1000+m.id}]=saved.notes[${1000+m.id}]==='complete'?'':'complete';persist();render()">${saved.notes[1000+m.id]==='complete'?'✓ Gate self-verified · undo':'I passed this lesson’s gate'}</button></div><p class="note">Mark the gate only after completing its exercise without solution help. Reading alone is not mastery.</p><article class="reader">${m.html}</article><div class="panel" style="margin-top:18px"><h3>Your proof & mistake notebook</h3><textarea data-mastery-note="${1100+m.id}" aria-label="Lesson notebook" placeholder="State the invariant, proof, failed approach, and changed-constraint result…">${esc(saved.notes[1100+m.id]||'')}</textarea><p class="note">Saved automatically in this browser and included in progress exports.</p></div><div class="controls">${m.id>0?`<a class="btn light" href="#deep/${m.id-1}">← Previous</a>`:''}${m.id<COURSE.mastery.length-1?`<a class="btn" href="#deep/${m.id+1}">Next lesson →</a>`:''}</div>`}
function labHome(){return heading('ORIGINAL PRACTICE · NO COMPANY CLAIMS','Interview labs','Attempt the prompt first. Reveal hints deliberately; save the follow-up for after your solution.')+`<p class="note">These are original training exercises, not reported Google interview questions. The solution is intentionally hidden until you choose to reveal it. No code is executed by this app.</p><div class="grid">${COURSE.labs.map((l,i)=>`<article class="card"><div class="card-top"><span class="phase-icon">L${i+1}</span><span class="tag">${l.time} MINUTES</span></div><h3>${esc(l.title)}</h3><p>${esc(l.topic)}</p><a class="btn light" href="#lab/${i}">Attempt lab →</a></article>`).join('')}</div>`}
function labPage(id){const l=COURSE.labs[+id];if(!l)return '<p>Lab not found. <a href="#labs">Return to labs.</a></p>';return heading('INTERVIEW LAB '+(+id+1),esc(l.title),`${l.time}-minute practice · ${esc(l.topic)}`)+`<div class="controls"><a class="btn light" href="#labs">← All labs</a><a class="btn light" href="#mocks">Open mock timer</a><a class="btn light" href="#readiness">Record a mock result →</a></div><article class="reader"><h3>The prompt</h3><p>${esc(l.prompt)}</p><h4>Example</h4><p>${esc(l.example)}</p><h4>Before opening a hint</h4><p>Write the contract, brute-force cost, and bottleneck. Then define the state or invariant. Implement in your own editor and record your reasoning below.</p><textarea data-mastery-note="${1200+(+id)}" aria-label="Lab working notes" placeholder="Approach, proof, pseudocode, test results, and hints used…">${esc(saved.notes[1200+(+id)]||'')}</textarea>${l.hints.map((h,i)=>`<details><summary>Hint ${i+1} · ${['Model the problem','Find the invariant','Shape the algorithm'][i]}</summary><p>${esc(h)}</p></details>`).join('')}<details><summary>Reveal solution reasoning, proof & complexity</summary><p>${esc(l.solution)}</p><h4>Adversarial checks</h4><ul>${l.tests.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="note">If you used the approach or solution, record this as assisted practice and re-solve from scratch later.</p></details><details><summary>Interviewer follow-up · change one assumption</summary><p>${esc(l.followup)}</p><details><summary>Reveal follow-up reasoning</summary><p>${esc(l.answer)}</p></details></details></article>`}
function mockRecords(){try{const a=JSON.parse(saved.notes[1999]||'[]');return Array.isArray(a)?a.filter(r=>r&&typeof r.title==='string'&&Array.isArray(r.scores)&&r.scores.length===5&&r.scores.every(v=>Number.isInteger(v)&&v>=0&&v<=4)&&typeof r.date==='string'):[]}catch{return []}}
const dimensions=['Understanding & constraints','Algorithm selection & complexity','Correctness reasoning','Implementation & testing','Communication & adaptation'];
function readinessPage(){const records=mockRecords(),fresh=records.filter(r=>r.unseen).slice(-3),pass=fresh.length===3&&fresh.every(r=>r.scores.reduce((a,b)=>a+b,0)>=16&&Math.min(...r.scores)>=3);return heading('EVIDENCE, NOT A GUARANTEE','Your readiness scorecard','Record unseen timed mocks honestly. Identify the skill that needs repair.')+`<div class="panel ${pass?'callout':''}"><h3>${pass?'Recent score target met':'Build evidence across three unseen mocks'}</h3><p>${pass?'Your last three recorded unseen mocks meet this app’s score threshold. Check topic breadth, retention, and follow-up performance before drawing conclusions.':'Suggested training target: at least 16/20 with every dimension ≥3 in each of three recent unseen mocks.'}</p><p class="note">This is a self-assessment heuristic, not Google’s hiring rubric. Use another person’s feedback when possible. Repeated or assisted questions should not be marked unseen independent practice.</p></div><form id="mock-form" class="panel" style="margin-top:18px"><h3>Record a practice interview</h3><label>Problem / lab and date context<input name="title" required maxlength="180" placeholder="e.g. Courier lab · first attempt" style="display:block;width:100%;margin:8px 0 18px"></label><label><input type="checkbox" name="unseen" style="min-width:0"> Unseen question, attempted independently before reading hints</label><p class="note">0 absent · 1 major help · 2 significant gaps · 3 independent with small corrections · 4 precise and adaptable</p><div class="score-grid">${dimensions.map((d,i)=>`<label>${d}<select name="score${i}" required aria-label="${d}"><option value="">Select score</option>${[0,1,2,3,4].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label>`).join('')}</div><label>Evidence & next repair<textarea name="evidence" required maxlength="4000" placeholder="Which proof was missing? What bug appeared? How did the follow-up go?"></textarea></label><button type="submit" class="btn" style="margin-top:12px">Save mock result</button></form><div class="panel" style="margin-top:18px"><h3>Practice history</h3>${records.length?records.slice().reverse().map(r=>`<div class="review-item" style="display:block"><strong>${esc(r.title)}</strong><p class="note">${esc(r.date)} · ${r.unseen?'Unseen independent attempt':'Retention / assisted practice'} · ${r.scores.reduce((a,b)=>a+b,0)}/20</p><p class="note">${dimensions.map((d,i)=>`${d}: ${r.scores[i]}`).join(' · ')}</p><p>${esc(r.evidence||'')}</p></div>`).join(''):'<p class="sub">No mocks recorded yet. One honest baseline is a useful start.</p>'}</div><div class="reader" style="margin-top:18px">${COURSE.mastery[13].html}</div>`}
function masteryBind(){document.querySelectorAll('[data-mastery-note]').forEach(el=>el.oninput=()=>{saved.notes[el.dataset.masteryNote]=el.value;persist()});const f=$('#mock-form');if(f)f.onsubmit=e=>{e.preventDefault();const values=new FormData(f),scores=dimensions.map((_,i)=>Number(values.get('score'+i)));if(scores.some(x=>!Number.isInteger(x)||x<0||x>4))return;const r={title:String(values.get('title')).trim(),unseen:values.get('unseen')==='on',scores,evidence:String(values.get('evidence')),date:new Date().toLocaleDateString()};if(!r.title)return;const records=mockRecords();records.push(r);saved.notes[1999]=JSON.stringify(records);persist();render();toast('Mock saved. Choose one concrete repair for the next session.')}}
